16	package org.springframework.samples.petclinic.model;
17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	import java.time.LocalDate;
22	import java.time.Period;
23	import java.time.temporal.ChronoUnit;
24	import java.util.Map;
25	
26	/**
27	 * Pure derivations of an {@link Owner}'s read-only attributes.
28	 *
29	 * <p>Each method computes one derived value from an owner's own field values and
30	 * nothing else, so the computations stay stateless and side-effect free. {@link Owner}
31	 * exposes these through thin {@code @Transient} getters that pass in the relevant
32	 * fields; keeping the arithmetic here rather than on the entity leaves {@code Owner}
33	 * to describe its persistent state and relationships while its growing family of
34	 * derived attributes lives together in one place.
35	 */
36	final class OwnerDerivations {
37	
38	    /** Fixed city-to-region table used to derive {@link #region}. */
39	    private static final Map<String, String> CITY_REGION = Map.of(
40	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
41	
42	    /** Region -> inclusive 4-digit postcode range {low, high} used to derive
43	     *  {@link #region} in preference to the city. */
44	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
45	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
46	
47	    private OwnerDerivations() {
48	    }
49	
50	    /**
51	     * The owner's locality, i.e. the canonical region it belongs to. This is read
52	     * from the region-and-hash {@code customerCode} identity: the region is the
53	     * {@code <REGION>} component that precedes the first {@code '-'} of the assigned
54	     * customer code (e.g. {@code NSW} for {@code NSW-9F86D081}). Until an owner has
55	     * been assigned a customer code (for example while its create request is still
56	     * being validated) this falls back to the region derived directly from its own
57	     * fields (see {@link #region(String, String)}).
58	     *
59	     * @return the canonical region string, or {@code "UNKNOWN"}
60	     */
61	    static String locality(String customerCode, String postcode, String city) {
62	        if (customerCode != null) {
63	            int dash = customerCode.indexOf('-');
64	            if (dash >= 0) {
65	                return customerCode.substring(0, dash);
66	            }
67	        }
68	        return region(postcode, city);
69	    }
70	
71	    /**
72	     * The canonical region derived for an owner from its own fields. The postcode is
73	     * consulted first: when it is present and falls within a known region's inclusive
74	     * 4-digit range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD
75	     * 4000-4099}) that region is returned. Only when the postcode is absent or in no
76	     * known range does this fall back to the fixed city-to-region table
77	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}),
78	     * returning {@code "UNKNOWN"} when the city is not in the table either. This yields
79	     * the same region for the known cities while disambiguating cities that share a name
80	     * via their postcode.
81	     *
82	     * @return the canonical region string, or {@code "UNKNOWN"}
83	     */
84	    static String region(String postcode, String city) {
85	        String byPostcode = regionForPostcode(postcode);
86	        if (byPostcode != null) {
87	            return byPostcode;
88	        }
89	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
90	    }
91	
92	    /**
93	     * The region whose inclusive postcode range contains the given postcode, or
94	     * {@code null} when the postcode is absent, not a four-digit number, or in no
95	     * known range.
96	     */
97	    private static String regionForPostcode(String postcode) {
98	        if (postcode == null || !postcode.matches("\\d{4}")) {
99	            return null;
100	        }
101	        int value = Integer.parseInt(postcode);
102	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
103	            int[] range = entry.getValue();
104	            if (value >= range[0] && value <= range[1]) {
105	                return entry.getKey();
106	            }
107	        }
108	        return null;
109	    }
110	
111	    /**
112	     * Whether the given {@code postcode} is acceptable for the given {@code region}: an
113	     * absent postcode is always accepted, a present postcode must be exactly four
114	     * digits and, when the region has a known inclusive postcode range
115	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), fall within
116	     * it. A region with no known range (for example {@code "UNKNOWN"}) accepts any
117	     * four-digit postcode.
118	     *
119	     * @return {@code true} if the postcode is absent or valid for the region
120	     */
121	    static boolean postcodeMatchesRegion(String postcode, String region) {
122	        if (postcode == null) {
123	            return true;
124	        }
125	        if (!postcode.matches("\\d{4}")) {
126	            return false;
127	        }
128	        int[] range = REGION_POSTCODES.get(region);
129	        if (range == null) {
130	            return true;
131	        }
132	        int value = Integer.parseInt(postcode);
133	        return value >= range[0] && value <= range[1];
134	    }
135	
136	    /**
137	     * The owner's membership level, a number from 1 to 4. The creation-time factors
138	     * are assessed first: starting at 1, add 1 when an {@code email} is present and add
139	     * 1 when {@code namesakeCount} is 0, capped at 3. Level 4 is then reached only once
140	     * the owner's tenure exceeds 365 days, measured as the number of whole days from its
141	     * {@code registrationDate} up to {@code asOf}. Because a newly created owner has zero
142	     * tenure, it never exceeds level 3 at creation.
143	     *
144	     * @return the membership level, from 1 to 4
145	     */
146	    static int membershipLevel(String email, Integer namesakeCount, LocalDate registrationDate,
147	            LocalDate asOf) {
148	        int level = 1;
149	        if (hasEmail(email)) {
150	            level++;
151	        }
152	        if (namesakeCount != null && namesakeCount == 0) {
153	            level++;
154	        }
155	        level = Math.min(level, 3);
156	        if (registrationDate != null && asOf != null
157	                && ChronoUnit.DAYS.between(registrationDate, asOf) > 365) {
158	            level++;
159	        }
160	        return level;
161	    }
162	
163	    /**
164	     * The owner's preferred contact channel: {@code "EMAIL"} when an {@code email}
165	     * is present, otherwise {@code "PHONE"}.
166	     *
167	     * @return {@code "EMAIL"} or {@code "PHONE"}
168	     */
169	    static String contactPreference(String email) {
170	        if (hasEmail(email)) {
171	            return "EMAIL";
172	        }
173	        return "PHONE";
174	    }
175	
176	    /**
177	     * Whether the owner has an email address on file, i.e. its {@code email} is present
178	     * and not blank. This is the single presence test the email-driven derivations share
179	     * (a membership-level factor and the {@link #contactPreference(String) contact
180	     * preference}), so they agree on exactly what counts as "has an email".
181	     */
182	    private static boolean hasEmail(String email) {
183	        return email != null && !email.isBlank();
184	    }
185	
186	    /**
187	     * The Luhn check digit (0-9) computed over the decimal digits contained in the
188	     * given {@code customerCode}, processed right-to-left with every second digit
189	     * doubled (and reduced by 9 when the double exceeds 9). Non-digit characters are
190	     * ignored, and an absent or digit-free customer code yields {@code 0}.
191	     *
192	     * @return the Luhn check digit, from 0 to 9
193	     */
194	    static int checkDigit(String customerCode) {
195	        int sum = 0;
196	        boolean doubleDigit = true;
197	        for (int i = (customerCode == null ? 0 : customerCode.length()) - 1; i >= 0; i--) {
198	            char c = customerCode.charAt(i);
199	            if (c < '0' || c > '9') {
200	                continue;
201	            }
202	            int d = c - '0';
203	            if (doubleDigit) {
204	                d *= 2;
205	                if (d > 9) {
206	                    d -= 9;
207	                }
208	            }
209	            sum += d;
210	            doubleDigit = !doubleDigit;
211	        }
212	        return (10 - (sum % 10)) % 10;
213	    }
214	
215	    /**
216	     * The owner's age band, derived from its {@code birthDate} measured against its
217	     * {@code registrationDate}: {@code "MINOR"} when the owner is under 18 on the
218	     * registration date, {@code "ADULT"} from 18 to 64, and {@code "SENIOR"} at 65 or
219	     * over. The age is the number of whole years between the two dates. Returns
220	     * {@code null} when either date is absent, so no band is reported for an owner
221	     * without a supplied birth date.
222	     *
223	     * @return {@code "MINOR"}, {@code "ADULT"}, {@code "SENIOR"}, or {@code null}
224	     */
225	    static String ageBand(LocalDate birthDate, LocalDate registrationDate) {
226	        if (birthDate == null || registrationDate == null) {
227	            return null;
228	        }
229	        int age = Period.between(birthDate, registrationDate).getYears();
230	        if (age < 18) {
231	            return "MINOR";
232	        }
233	        if (age < 65) {
234	            return "ADULT";
235	        }
236	        return "SENIOR";
237	    }
238	
239	    /**
240	     * The single derived key used for duplicate detection, formed as
241	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
242	     * The telephone is the owner's stored (E.164-normalised) telephone, the email
243	     * is the stored (lower-cased) email or the empty string when absent, and the
244	     * household component is the stored {@code householdId} or the empty string
245	     * when the owner belongs to no household.
246	     *
247	     * @return the owner's identity key
248	     */
249	    static String identityKey(String telephone, String email, String householdId) {
250	        String tel = telephone == null ? "" : telephone;
251	        String mail = email == null ? "" : email;
252	        String household = householdId == null ? "" : householdId;
253	        return tel + "|" + mail + "|" + household;
254	    }
255	
256	    /**
257	     * The owner's customer code, formatted {@code <REGION>-<HASH8>}: {@code region} is
258	     * the owner's canonical region (see {@link #region(String, String)}) and HASH8 is the
259	     * first eight upper-case hexadecimal characters of the SHA-256 digest of the owner's
260	     * normalised telephone concatenated with its last name (e.g. {@code NSW-9F86D081}).
261	     *
262	     * @return the customer code
263	     */
264	    static String customerCode(String region, String telephone, String lastName) {
265	        String hash8 = sha256Hex(telephone + lastName).substring(0, 8).toUpperCase();
266	        return String.format("%s-%s", region, hash8);
267	    }
268	
269	    /**
270	     * The stable identifier for the household an owner belongs to, derived
271	     * deterministically from its {@code normalizedLastName} and {@code postcode} so that
272	     * every owner sharing a last name and postcode resolves to the same value. It is the
273	     * first twelve lower-case hexadecimal characters of the SHA-256 digest of
274	     * {@code normalizedLastName + '|' + postcode} (an absent postcode contributes the
275	     * empty string).
276	     *
277	     * @return the household identifier
278	     */
279	    static String householdId(String normalizedLastName, String postcode) {
280	        String pc = postcode == null ? "" : postcode;
281	        return sha256Hex(normalizedLastName + "|" + pc).substring(0, 12);
282	    }
283	
284	    /**
285	     * The SHA-256 digest of the UTF-8 bytes of the given value, as a lower-case
286	     * hexadecimal string. Callers take the prefix and case they need.
287	     */
288	    static String sha256Hex(String value) {
289	        try {
290	            byte[] digest = MessageDigest.getInstance("SHA-256")
291	                .digest(value.getBytes(StandardCharsets.UTF_8));
292	            StringBuilder hex = new StringBuilder(digest.length * 2);
293	            for (byte b : digest) {
294	                hex.append(String.format("%02x", b));
295	            }
296	            return hex.toString();
297	        } catch (NoSuchAlgorithmException e) {
298	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
299	        }
300	    }
301	}
