371	    /**
372	     * Normalise a value for case-insensitive, whitespace-insensitive comparison:
373	     * trim, collapse internal runs of whitespace to a single space and lower-case.
374	     */
375	    private static String normalize(String value) {
376	        if (value == null) {
377	            return "";
378	        }
379	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
380	    }
381	
382	    /**
383	     * Reduce an address to its canonical stored form: trim and collapse runs of
384	     * whitespace to a single space, upper-case, and expand common abbreviations
385	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}) whenever
386	     * they appear as whole words. The result is what is stored, returned and used
387	     * for every household comparison; it is idempotent, so re-normalising an
388	     * already-normalised address leaves it unchanged.
389	     *
390	     * @param value the raw address (may be {@code null})
391	     * @return the normalised address, or the empty string if {@code value} is
392	     *         {@code null} or blank
393	     */
394	    public static String normalizeAddress(String value) {
395	        if (value == null) {
396	            return "";
397	        }
398	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
399	        if (collapsed.isEmpty()) {
400	            return "";
401	        }
402	        String[] tokens = collapsed.split(" ");
403	        for (int i = 0; i < tokens.length; i++) {
404	            tokens[i] = switch (tokens[i]) {
405	                case "ST" -> "STREET";
406	                case "RD" -> "ROAD";
407	                case "AVE" -> "AVENUE";
408	                default -> tokens[i];
409	            };
410	        }
411	        return String.join(" ", tokens);
412	    }
