    int level = 1;
    if (hasEmail(email)) {
        level++;
    }
    if (namesakeCount != null && namesakeCount == 0) {
        level++;
    }
    level = Math.min(level, 3);
    if (tenureExceedsYear(registrationDate, asOf)) {
        level++;
    }
    return level;
